<script setup>
import { ref } from 'vue'
import bank from '@/data/scene850.json'
import { useLearnerStore } from '@/stores/learner'
import { speakText } from '@/services/audio'
import { explainWord } from '@/services/llm'
const props=defineProps({sentences:Array,translation:Boolean,scene:String,active:{default:-1},hidden:Boolean}),emit=defineEmits(['support','select'])
const learner=useLearnerStore(),selected=ref(null),explanation=ref(null),loading=ref(false),error=ref('');let requestId=0
function parts(text){return text.split(/([A-Za-z]+(?:'[A-Za-z]+)?)/g).filter(Boolean).map(t=>({text:t,word:/^[A-Za-z]+(?:'[A-Za-z]+)?$/.test(t)}))}
function find(word){const key=word.toLowerCase();return bank.rows.find(r=>r.lookup===key)||bank.rows.find(r=>r.lookup===key.replace(/s$/,''))}
async function open(word,index){const id=++requestId;const row=find(word);selected.value={word,index,row};explanation.value=null;error.value='';learner.needHelp(row?.lookup||word.toLowerCase(),props.scene);emit('support',row?.lookup||word.toLowerCase());loading.value=true;try{const data=await explainWord({word,context:props.sentences[index][0]});if(id!==requestId)return;const next={english:data.english||'',chinese:data.chinese||'',example:data.example||'',exampleChinese:data.exampleChinese||''};if(next.english||next.chinese||next.example)explanation.value=next;else error.value=row?'可以先听发音，结合原句理解。':'此词不在主要图谱里，可问 Alex 解释当前句。'}catch{if(id===requestId)error.value=row?'可以先听发音，结合原句理解。':'此词不在主要图谱里，可问 Alex 解释当前句。'}finally{if(id===requestId)loading.value=false}}
</script>
<template><div class="passage" :class="{masked:hidden}"><template v-if="!hidden"><div v-for="(row,index) in sentences" :key="index" class="sentence" :class="{active:active===index}"><p class="reading-font"><template v-for="(part,j) in parts(row[0])" :key="j"><button v-if="part.word" class="word" @click="open(part.text,index)">{{part.text}}</button><span v-else>{{part.text}}</span></template></p><p v-if="translation" class="translation">{{row[1]}}</p>
<aside v-if="selected?.index===index" class="word-detail" aria-live="polite"><button class="close-word" aria-label="关闭解释" @click="selected=null;requestId++">×</button><div class="word-heading"><strong>{{selected.word}}</strong><span>{{selected.row?.phonetic?`/${selected.row.phonetic}/`:'音标待补，可听发音'}}</span><button class="btn btn-secondary" @click="speakText(selected.word)">听发音</button></div><p>{{selected.row?.meaning||'场景扩展词'}}</p><p v-if="loading" class="muted">正在看它在原句里的意思…</p><p v-if="explanation?.english">{{explanation.english}}</p><p v-if="explanation?.chinese">{{explanation.chinese}}</p><p v-if="explanation?.example">例句：{{explanation.example}}<span v-if="explanation.exampleChinese">（{{explanation.exampleChinese}}）</span></p><p v-if="error" class="muted">{{error}}</p><small>原句：{{row[0]}}</small><p v-if="selected.row?.chunk" class="muted">常用搭配：{{selected.row.chunk}}</p><button class="btn btn-ghost" @click="emit('select',index);selected=null">在原句里跟读</button></aside></div></template><div v-else class="masked-message">原文已遮住。边听边写，随时重听。</div></div></template>
<style scoped>.passage{padding:16px 28px 30px}.sentence{padding:9px 12px;border-radius:12px}.sentence.active{background:#eaf5ed}.sentence>.reading-font{font-size:23px;line-height:1.85;margin:0}.word{font:inherit;border:0;padding:0;background:transparent;color:var(--ink);border-bottom:1px dotted #abc7b4}.word:hover{background:#e8f3ed;color:var(--brand)}.translation{color:var(--ink-muted);font-size:13px;margin:5px 0}.word-detail{position:relative;margin:12px 0 3px;padding:20px;background:#f3f8f4;border:1px solid var(--line);border-radius:15px;font-size:13px}.word-heading{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.word-heading strong{font-size:25px}.word-heading span{color:var(--ink-muted);font-size:12px}.word-heading .btn{padding:6px 12px;min-height:34px;font-size:12px}.close-word{position:absolute;top:8px;right:10px;font-size:20px;border:0;background:transparent;color:var(--ink-muted)}.word-detail p{margin:8px 0}.word-detail small{line-height:1.8;display:block}.masked-message{padding:40px 0;text-align:center;color:var(--ink-muted);border:1px dashed var(--line);border-radius:15px}@media(max-width:750px){.passage{padding:13px 10px 20px}.sentence>.reading-font{font-size:21px}}</style>
